/**
 * An email allow policy
 */
export type EmailSecurityAllowPolicy = {
    comments?: string | null;
    created_at: EmailSecurityTimestamp;
    id: EmailSecurityAllowPolicyId;
    /**
     * Messages from this sender will be exempted from Spam, Spoof and Bulk dispositions. Note - This will not exempt messages with Malicious or Suspicious dispositions.
     */
    is_acceptable_sender?: boolean;
    /**
     * Messages to this recipient will bypass all detections
     */
    is_exempt_recipient?: boolean;
    /**
     * Deprecated as of July 1, 2025. Use `is_exempt_recipient` instead. End of life: July 1, 2026.
     *
     * @deprecated
     */
    is_recipient?: boolean;
    is_regex?: boolean;
    /**
     * Deprecated as of July 1, 2025. Use `is_trusted_sender` instead. End of life: July 1, 2026.
     *
     * @deprecated
     */
    is_sender?: boolean;
    /**
     * Deprecated as of July 1, 2025. Use `is_acceptable_sender` instead. End of life: July 1, 2026.
     *
     * @deprecated
     */
    is_spoof?: boolean;
    /**
     * Messages from this sender will bypass all detections and link following
     */
    is_trusted_sender?: boolean;
    /**
     * Deprecated, use `modified_at` instead. End of life: November 1, 2026.
     *
     * @deprecated
     */
    last_modified: EmailSecurityTimestamp;
    modified_at?: EmailSecurityTimestamp;
    pattern?: string;
    pattern_type?: EmailSecurityPatternType;
    /**
     * Enforce DMARC, SPF or DKIM authentication. When on, Email Security only honors policies that pass authentication.
     */
    verify_sender?: boolean;
};

