export type MqIdentifier = string;

/**
 * An ID that represents an "in-flight" message that has been pulled from a Queue. You must hold on to this ID and use it to acknowledge this message.
 */
export type MqLeaseId = string;

/**
 * Maximum number of concurrent consumers that may consume from this Queue. Set to `null` to automatically opt in to the platform's maximum (recommended).
 */
export type MqMaxConcurrency = number;

/**
 * The maximum number of retries
 */
export type MqMaxRetries = number;

/**
 * The number of milliseconds to wait for a batch to fill up before attempting to deliver it
 */
export type MqMaxWaitTime = number;

export type MqProducer = MqWorkerProducer | MqR2Producer;

export type MqQueue = {
    readonly consumers?: Array<MqConsumerResponse>;
    readonly consumers_total_count?: number;
    readonly created_on?: string;
    readonly modified_on?: string;
    readonly producers?: Array<MqProducer>;
    readonly producers_total_count?: number;
    readonly queue_id?: string;
    queue_name?: MqQueueName;
    settings?: MqQueueSettings;
};

export type MqQueueBatch = {
    /**
     * The number of seconds to wait for attempting to deliver this batch to consumers
     */
    delay_seconds?: number;
    messages?: Array<MqQueueMessage>;
};

export type MqQueueMessage = {
    /**
     * The number of seconds to wait for attempting to deliver this message to consumers
     */
    delay_seconds?: number;
} & (MqQueueMessageText | MqQueueMessageJson);

export type MqQueueMessageJson = {
    body?: {
        [key: string]: unknown;
    };
    content_type?: 'json';
};

export type MqQueueMessageText = {
    body?: string;
    content_type?: 'text';
};

/**
 * Best-effort metrics for the queue. Values may be approximate due to the distributed nature of queues.
 */
export type MqQueueMetrics = {
    /**
     * The size in bytes of unacknowledged messages in the queue.
     */
    backlog_bytes: number;
    /**
     * The number of unacknowledged messages in the queue.
     */
    backlog_count: number;
    /**
     * Unix timestamp in milliseconds of the oldest unacknowledged message in the queue. Returns 0 if unknown.
     */
    oldest_message_timestamp_ms: number;
};

export type MqQueueName = string;

export type MqQueuePullBatch = Array<{
    readonly attempts?: number;
    readonly body?: string;
    readonly id?: string;
    lease_id?: MqLeaseId;
    readonly timestamp_ms?: number;
}>;

export type MqQueueSettings = {
    /**
     * Number of seconds to delay delivery of all messages to consumers.
     */
    delivery_delay?: number;
    /**
     * Indicates if message delivery to consumers is currently paused.
     */
    delivery_paused?: boolean;
    /**
     * Number of seconds after which an unconsumed message will be delayed.
     */
    message_retention_period?: number;
};

export type MqR2Producer = {
    bucket_name?: string;
    type?: 'r2_bucket';
};

/**
 * The number of seconds to delay before making the message available for another attempt.
 */
export type MqRetryDelay = number;

/**
 * Name of a Worker
 */
export type MqScriptName = string;

/**
 * The number of milliseconds that a message is exclusively leased. After the timeout, the message becomes available for another attempt.
 */
export type MqVisibilityTimeout = number;

export type MqWorkerConsumerRequest = {
    dead_letter_queue?: MqQueueName;
    script_name: MqScriptName;
    settings?: {
        batch_size?: MqBatchSize;
        max_concurrency?: MqMaxConcurrency;
        max_retries?: MqMaxRetries;
        max_wait_time_ms?: MqMaxWaitTime;
        retry_delay?: MqRetryDelay;
    };
    type: 'worker';
};

export type MqWorkerConsumerResponse = {
    consumer_id?: MqIdentifier;
    created_on?: string;
    /**
     * Name of the dead letter queue, or empty string if not configured
     */
    dead_letter_queue?: string;
    queue_name?: MqQueueName;
    script_name?: MqScriptName;
    settings?: {
        batch_size?: MqBatchSize;
        max_concurrency?: MqMaxConcurrency;
        max_retries?: MqMaxRetries;
        max_wait_time_ms?: MqMaxWaitTime;
        retry_delay?: MqRetryDelay;
    };
    type?: 'worker';
};

export type MqWorkerProducer = {
    script?: string;
    type?: 'worker';
};

