/**
 * Preset
 */
export type RealtimekitPreset = {
    config: {
        /**
         * Maximum number of screen shares that can be active at a given time
         */
        max_screenshare_count: number;
        /**
         * Maximum number of streams that are visible on a device
         */
        max_video_streams: {
            /**
             * Maximum number of video streams visible on desktop devices
             */
            desktop: number;
            /**
             * Maximum number of streams visible on mobile devices
             */
            mobile: number;
        };
        /**
         * Media configuration options. eg: Video quality
         */
        media: {
            /**
             * Control options for Audio quality.
             */
            audio?: {
                /**
                 * Enable High Quality Audio for your meetings
                 */
                enable_high_bitrate?: boolean;
                /**
                 * Enable Stereo for your meetings
                 */
                enable_stereo?: boolean;
            };
            /**
             * Configuration options for participant screen shares
             */
            screenshare: {
                /**
                 * Frame rate of screen share
                 */
                frame_rate: number;
                /**
                 * Quality of screen share
                 */
                quality: 'hd' | 'vga' | 'qvga';
            };
            /**
             * Configuration options for participant videos
             */
            video: {
                /**
                 * Frame rate of participants' video
                 */
                frame_rate: number;
                /**
                 * Video quality of participants
                 */
                quality: 'hd' | 'vga' | 'qvga';
            };
        };
        /**
         * Type of the meeting
         */
        view_type: 'GROUP_CALL' | 'WEBINAR' | 'AUDIO_ROOM';
    };
    /**
     * Name of the preset
     */
    name: string;
    permissions?: {
        /**
         * Whether this participant can accept waiting requests
         */
        accept_waiting_requests: boolean;
        can_accept_production_requests: boolean;
        can_change_participant_permissions: boolean;
        can_edit_display_name: boolean;
        can_livestream: boolean;
        can_record: boolean;
        can_spotlight: boolean;
        /**
         * Chat permissions
         */
        chat: {
            private: {
                can_receive: boolean;
                can_send: boolean;
                files: boolean;
                text: boolean;
            };
            public: {
                /**
                 * Can send messages in general
                 */
                can_send: boolean;
                /**
                 * Can send file messages
                 */
                files: boolean;
                /**
                 * Can send text messages
                 */
                text: boolean;
            };
        };
        connected_meetings: {
            can_alter_connected_meetings: boolean;
            can_switch_connected_meetings: boolean;
            can_switch_to_parent_meeting: boolean;
        };
        disable_participant_audio: boolean;
        disable_participant_screensharing: boolean;
        disable_participant_video: boolean;
        /**
         * Whether this participant is visible to others or not
         */
        hidden_participant: boolean;
        is_recorder?: boolean;
        kick_participant: boolean;
        /**
         * Media permissions
         */
        media: {
            /**
             * Audio permissions
             */
            audio: {
                /**
                 * Can produce audio
                 */
                can_produce: 'ALLOWED' | 'NOT_ALLOWED' | 'CAN_REQUEST';
            };
            /**
             * Screenshare permissions
             */
            screenshare: {
                /**
                 * Can produce screen share video
                 */
                can_produce: 'ALLOWED' | 'NOT_ALLOWED' | 'CAN_REQUEST';
            };
            /**
             * Video permissions
             */
            video: {
                /**
                 * Can produce video
                 */
                can_produce: 'ALLOWED' | 'NOT_ALLOWED' | 'CAN_REQUEST';
            };
        };
        pin_participant: boolean;
        /**
         * Plugin permissions
         */
        plugins: {
            /**
             * Can close plugins that are already open
             */
            can_close: boolean;
            /**
             * Can edit plugin config
             */
            can_edit_config: boolean;
            /**
             * Can start plugins
             */
            can_start: boolean;
            config: string | {
                access_control: 'FULL_ACCESS' | 'VIEW_ONLY';
                handles_view_only: boolean;
            };
        };
        /**
         * Poll permissions
         */
        polls: {
            /**
             * Can create polls
             */
            can_create: boolean;
            /**
             * Can view polls
             */
            can_view: boolean;
            /**
             * Can vote on polls
             */
            can_vote: boolean;
        };
        /**
         * Type of the recording peer
         */
        recorder_type: 'RECORDER' | 'LIVESTREAMER' | 'NONE';
        show_participant_list: boolean;
        /**
         * Waiting room type
         */
        waiting_room_type: 'SKIP' | 'ON_PRIVILEGED_USER_ENTRY' | 'SKIP_ON_ACCEPT';
    };
    ui: {
        config_diff?: {
            [key: string]: unknown;
        };
        design_tokens: {
            border_radius: 'rounded';
            border_width: 'thin';
            colors: {
                background: {
                    600: string;
                    700: string;
                    800: string;
                    900: string;
                    1000: string;
                };
                brand: {
                    300: string;
                    400: string;
                    500: string;
                    600: string;
                    700: string;
                };
                danger: string;
                success: string;
                text: string;
                text_on_brand: string;
                video_bg: string;
                warning: string;
            };
            logo: string;
            spacing_base: number;
            theme: 'dark';
        };
    };
};

