export type AccessSchemasIdentityProviderWritable = {
    id?: AccessUuid;
    name: AccessComponentsSchemasName;
    /**
     * The configuration settings for enabling a System for Cross-Domain Identity Management (SCIM) with the identity provider.
     */
    scim_config?: {
        /**
         * A flag to enable or disable SCIM for the identity provider.
         */
        enabled?: boolean;
        /**
         * Indicates how a SCIM event updates a user identity used for policy evaluation. Use "automatic" to automatically update a user's identity and augment it with fields from the SCIM user resource. Use "reauth" to force re-authentication on group membership updates, user identity update will only occur after successful re-authentication. With "reauth" identities will not contain fields from the SCIM user resource. With "no_action" identities will not be changed by SCIM updates in any way and users will not be prompted to reauthenticate.
         */
        identity_update_behavior?: 'automatic' | 'reauth' | 'no_action';
        /**
         * A flag to remove a user's seat in Zero Trust when they have been deprovisioned in the Identity Provider.  This cannot be enabled unless user_deprovision is also enabled.
         */
        seat_deprovision?: boolean;
        /**
         * A flag to enable revoking a user's session in Access and Gateway when they have been deprovisioned in the Identity Provider.
         */
        user_deprovision?: boolean;
    };
    /**
     * The type of identity provider. To determine the value for a specific provider, refer to our [developer documentation](https://developers.cloudflare.com/cloudflare-one/identity/idp-integration/).
     */
    type: 'onetimepin' | 'azureAD' | 'saml' | 'centrify' | 'facebook' | 'github' | 'google-apps' | 'google' | 'linkedin' | 'oidc' | 'okta' | 'onelogin' | 'pingone' | 'yandex';
};

