/**
 * Cache Reserve
 *
 * Increase cache lifetimes by automatically storing all cacheable files into Cloudflare's persistent object storage buckets. Requires Cache Reserve subscription. Note: using Tiered Cache with Cache Reserve is highly recommended to reduce Reserve operations costs. See the [developer docs](https://developers.cloudflare.com/cache/about/cache-reserve) for more information.
 */
export type CacheRulesCacheReserveWritable = CacheRulesBaseWritable & {
    /**
     * ID of the zone setting.
     */
    id?: 'cache_reserve';
};

/**
 * Cache Reserve Clear
 *
 * You can use Cache Reserve Clear to clear your Cache Reserve, but you must first disable Cache Reserve. In most cases, this will be accomplished within 24 hours. You cannot re-enable Cache Reserve while this process is ongoing. Keep in mind that you cannot undo or cancel this operation.
 */
export type CacheRulesCacheReserveClearWritable = CacheRulesBaseWritable & {
    /**
     * ID of the zone setting.
     */
    id?: 'cache_reserve_clear';
};

export type CacheRulesCacheReserveClearResponseValueWritable = {
    result?: CacheRulesCacheReserveClearWritable & {
        end_ts?: CacheRulesCacheReserveClearEndTs;
        start_ts: CacheRulesCacheReserveClearStartTs;
        state: CacheRulesCacheReserveClearState;
    };
};

export type CacheRulesCacheReserveResponseValueWritable = {
    result?: CacheRulesCacheReserveWritable & {
        value: CacheRulesCacheReserveValue;
    };
};

/**
 * Origin H2 Max Streams
 *
 * Origin H2 Max Streams configures the max number of concurrent requests that Cloudflare will send within the same connection when communicating with the origin server, if the origin supports it. Note that if your origin does not support H2 multiplexing, 5xx errors may be observed, particularly 520s. Also note that the default value is `100` for all plan types except Enterprise where it is `1`. `1` means that H2 multiplexing is disabled.
 */
export type CacheRulesOriginH2MaxStreamsWritable = CacheRulesBaseWritable & {
    /**
     * Value of the zone setting.
     */
    id?: 'origin_h2_max_streams';
    value?: CacheRulesOriginH2MaxStreamsValue;
};

export type CacheRulesOriginH2MaxStreamsResponseValueWritable = CacheRulesApiResponseCommon & {
    result?: CacheRulesOriginH2MaxStreamsWritable;
};

/**
 * Origin Max HTTP Version
 *
 * Origin Max HTTP Setting Version sets the highest HTTP version Cloudflare will attempt to use with your origin. This setting allows Cloudflare to make HTTP/2 requests to your origin. (Refer to [Enable HTTP/2 to Origin](https://developers.cloudflare.com/cache/how-to/enable-http2-to-origin/), for more information.). The default value is "2" for all plan types except Enterprise where it is "1".
 */
export type CacheRulesOriginMaxHttpVersionWritable = CacheRulesBaseWritable & {
    /**
     * Value of the zone setting.
     */
    id?: 'origin_max_http_version';
    value?: CacheRulesOriginMaxHttpVersionValue;
};

export type CacheRulesOriginMaxHttpVersionResponseValueWritable = {
    result?: CacheRulesOriginMaxHttpVersionWritable;
};

/**
 * Origin Post-Quantum Encryption
 *
 * Instructs Cloudflare to use Post-Quantum (PQ) key agreement algorithms when connecting to your origin. Preferred instructs Cloudflare to opportunistically send a Post-Quantum keyshare in the first message to the origin (for fastest connections when the origin supports and prefers PQ), supported means that PQ algorithms are advertised but only used when requested by the origin, and off means that PQ algorithms are not advertised.
 */
export type CacheRulesOriginPostQuantumEncryptionWritable = CacheRulesBaseWritable & {
    /**
     * Value of the zone setting.
     */
    id?: 'origin_pqe';
};

export type CacheRulesOriginPostQuantumEncryptionResponseValueWritable = {
    result?: CacheRulesOriginPostQuantumEncryptionWritable & {
        value: CacheRulesOriginPostQuantumEncryptionValue;
    };
};

